// v24.xx (sndA5), HIS ORDER 2026-10-12 (improve the sound, a distinct noise for every action): THE ROLL. A roll played the thin
// generic ping (a clank with no material: the menu no, a jam, a smoke landing), a roll refused for want of stamina played the very
// same ping, and the landing was silent (steps are muted for the 0.38 s of the roll). Now:
//   THE ROLL: a 0.25 s swell of cloth and gear, a lowpassed noise sweeping 300 Hz to 1.2 kHz, with two small kit rattles in it.
//   TOO TIRED: a short spent exhale (a soft band of breath, not a word) over a low dull thud, nothing like the roll.
//   THE LANDING: as the roll ends, a body knock (110 to 60 Hz) and the grit of what you landed on (stone, boards, a grate, leaves,
//     water). Your own ears only, so the party does not hear your feet twice. No seeded draw.
SND_CAT.roll='foley'; SND_CAT.rollno='foley'; SND_CAT.rollland='foley';
SNDA_GEN.roll=function(a,OUT,vol,t){
  if(!sndAGate('roll',0.15,t)) return;
  sndANoise(a,OUT,{dur:0.25,swell:0.7,ft:'lowpass',f0:300,f1:1200,q:0.9,g:0.16*vol,at:t});
  sndANoise(a,OUT,{dur:0.012,pw:2,ft:'bandpass',f0:2400,q:4,g:0.07*vol,at:t+0.04});
  sndANoise(a,OUT,{dur:0.012,pw:2,ft:'bandpass',f0:2650,q:4,g:0.05*vol,at:t+0.1});
};
SNDA_GEN.rollno=function(a,OUT,vol,t){
  if(!sndAGate('rollno',0.3,t)) return;
  sndANoise(a,OUT,{dur:0.17,swell:0.35,ft:'bandpass',f0:950,f1:700,q:0.9,g:0.12*vol,at:t});
  sndATone(a,OUT,'sine',110,70,0.09,0.16*vol,t);
};
SNDA_GEN.rollland=function(a,OUT,vol,t,surf){
  var F={water:['bandpass',1200,1.2,0.07],leaf:['highpass',3200,0.6,0.05],metal:['bandpass',3400,6,0.05],wood:['lowpass',420,3,0.09]}[surf]||['bandpass',1500,1.4,0.07];
  if(!sndAGate('rollland',0.15,t)) return;
  sndATone(a,OUT,'sine',110,60,0.09,0.2*vol,t);
  sndANoise(a,OUT,{dur:surf==='water'?0.12:0.05,pw:2.2,ft:F[0],f0:F[1],q:F[2],g:F[3]*vol,at:t});
};
